package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializationConfig;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen0Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // Concrete class for testing "Potential Bean Type"
    public static class TestBean {
        public String name;
    }

    // Abstract class for testing "materializeAbstractType"
    public abstract static class AbstractBean {
        public abstract void doSomething();
    }

    public static class ConcreteBean extends AbstractBean {
        @Override public void doSomething() {}
    }

    @Before
    public void setUp() {
        factory = Mockito.spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        type = mock(JavaType.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testCreateBeanDeserializer_ReturnsCustomDeserializer() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = mock(JsonDeserializer.class);
        doReturn(customDeser).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(factory, never()).buildThrowableDeserializer(any(), any(), any());
    }

    @Test
    public void testCreateBeanDeserializer_ReturnsThrowableDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(true);

        JsonDeserializer<Object> throwableDeser = mock(JsonDeserializer.class);
        doReturn(throwableDeser).when(factory).buildThrowableDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(throwableDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_MaterializesAbstractType() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);

        JavaType concreteType = typeFactory.constructType(ConcreteBean.class);
        doReturn(concreteType).when(factory).materializeAbstractType(any(), any(), any());

        BeanDescription newBeanDesc = mock(BeanDescription.class);
        doReturn(newBeanDesc).when(config).introspect(concreteType);

        JsonDeserializer<Object> beanDeser = mock(JsonDeserializer.class);
        doReturn(beanDeser).when(factory).buildBeanDeserializer(any(), eq(concreteType), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_ReturnsStdDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);

        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);
        doReturn(stdDeser).when(factory).findStdDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_ReturnsNullWhenNotPotentialBean() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        // Mocking a non-bean type (like a String)
        when(type.getRawClass()).thenReturn(String.class);
        doReturn(false).when(factory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    @Test
    public void testCreateBeanDeserializer_BuildsBeanDeserializerForPotentialBean() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        when(type.getRawClass()).thenReturn(TestBean.class);
        doReturn(true).when(factory).isPotentialBeanType(TestBean.class);

        JsonDeserializer<Object> beanDeser = mock(JsonDeserializer.class);
        doReturn(beanDeser).when(factory).buildBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractPrimitiveCheck() throws JsonMappingException {
        // Ensures that if type is abstract AND primitive, it skips materialization logic
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(true);

        // Should fall through to findStdDeserializer
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        when(type.getRawClass()).thenReturn(Integer.class);
        doReturn(false).when(factory).isPotentialBeanType(any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);
        assertNull(result);
    }
}
